class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is DeviceIdentity) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    }    else if (value is SystemInfo) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    }    else if (value is CpuCore) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    }    else if (value is CpuInfo) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is GpuInfo) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is MemoryStats) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is StorageVolumeInfo) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is StorageInfo) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is BatteryInfo) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is DisplayInfo) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is NetworkInfo) {
      buffer.putUint8(139);
